const API = "https://tryjuraaah.vercel.app/api/agent";
const N8N = "https://mohammad-aljry.app.n8n.cloud/webhook";

const ID = /^[A-Za-z0-9_-]{1,64}$/;
const IMAGE_TYPES = /^(image\/(jpeg|png|webp|heic|heif))$/;
// 10 MB of image is ~13.4 MB of base64 - under n8n's default 16 MB request payload limit.
const MAX_IMAGE_BYTES = 10 * 1024 * 1024;
function imageOf(b, allowPdf) {
  const mime = typeof b.mimeType === 'string' ? b.mimeType.toLowerCase() : '';
  const data = typeof b.imageBase64 === 'string' ? b.imageBase64.replace(/^data:[^,]*,/, '').replace(/\s+/g, '') : '';
  if (!(IMAGE_TYPES.test(mime) || (allowPdf && mime === 'application/pdf'))) return { error: 'unsupported_mime_type' };
  if (!data || !/^[A-Za-z0-9+/]+={0,2}$/.test(data)) return { error: 'image_missing_or_not_base64' };
  const bytes = Math.floor(data.length * 3 / 4);
  if (bytes > MAX_IMAGE_BYTES) return { error: 'image_too_large' };
  return { mime, data, bytes };
}

const BRAND_PROMPT = "Look at this photo and return JSON matching the schema. You transcribe; you never decide what the medicine is, and you never look anything up.\n\nisMedicine is true for a medicine package, blister strip, bottle or pharmacy label - an over-the-counter product or a supplement in pharmaceutical packaging counts too. isMedicine is false for anything else (a receipt, a room, a hand, food, a document that is not a pharmacy label).\n\nWhen isMedicine is false: brandAsPrinted is null, ingredientsAsPrinted is [], strengthAsPrinted is null. Stop there - do not try to read a name off something that is not medicine packaging.\n\nWhen isMedicine is true:\n- brandAsPrinted is the FULL trade (brand) name exactly as printed IN LATIN LETTERS, including any variant word printed with it (for example \"Extra\", \"Night\", \"Cold & Flu\", \"Plus\", \"Forte\"). null if no Latin trade name is printed, or if you cannot read it clearly. Never transliterate an Arabic-only name into Latin letters yourself - if only Arabic script is printed, leave this null.\n- ingredientsAsPrinted lists each active ingredient name exactly as printed, in printed order. Empty array if none is printed or legible.\n- strengthAsPrinted is the strength exactly as printed (for example \"400 mg\", \"500 mg / 125 mg\"). null if not printed or not legible.\n\nNever guess. Never expand an abbreviation. Never supply a brand, ingredient or strength that is not visibly printed - a field you cannot read clearly is null (or [] for ingredientsAsPrinted), never a plausible guess.";
const TC_RESPONSE_SCHEMA = {"type":"object","properties":{"isMedicine":{"type":"boolean"},"brandAsPrinted":{"type":"string","nullable":true},"ingredientsAsPrinted":{"type":"array","items":{"type":"string"}},"strengthAsPrinted":{"type":"string","nullable":true}},"required":["isMedicine","brandAsPrinted","ingredientsAsPrinted","strengthAsPrinted"]};
// Body: { patientId, imageBase64, mimeType, language }. The profile is read from the BACKEND, never from the caller.
const b = $input.first().json.body || {};
const patientId = String(b.patientId || '');
if (!ID.test(patientId)) return [{ json: { valid: false, ok: false, error: 'invalid_patient_id' } }];
const img = imageOf(b, false);
if (img.error) return [{ json: { valid: false, ok: false, error: img.error } }];
return [{ json: { valid: true, patientId, language: b.language === 'en' ? 'en' : 'ar',
  rxUrl: API + '/patients/' + encodeURIComponent(patientId) + '/prescriptions',
  visionBody: { contents: [{ role: 'user', parts: [{ text: BRAND_PROMPT }, { inlineData: { mimeType: img.mime, data: img.data } }] }],
                generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: TC_RESPONSE_SCHEMA } } } }];

const c = $('check (deterministic)').first().json;
const result = c.result;
let alertStatus = null;
let alertId = null;
try {
  const w = $('backend: raise the alert').first().json;
  alertStatus = w.statusCode;
  if (w.statusCode === 201 && w.body && w.body.alert) alertId = w.body.alert.id;
} catch (e) { /* no alert was raised */ }
const appOutcome = Object.assign({}, result.appOutcome);
if (alertId && appOutcome.kind === 'identified' && appOutcome.verdict === 'interaction_found') appOutcome.alertId = alertId;
const mustEscalate = (c.post && alertStatus !== 201) || !!result.mustEscalate;
return [{ json: { ok: !c.error && !mustEscalate, error: c.error || (c.post && alertStatus !== 201 ? 'backend_refused_alert_' + alertStatus : null),
  mustEscalate, appOutcome, verdict: result.verdict, message: result.message || null, alertId,
  result: Object.assign({}, result, { alert: undefined }) } }];
